declare @topicId uniqueidentifier
SELECT @topicId=TopicId FROM PFM_SVBS_Topic_P where TopicFriendlyName = '';

DELETE FROM PFM_SVBS_Topic_P_LU_PFM_SVBS_TYPE_R where TopicId = @topicId;
DELETE FROM PFM_SVBS_Topic_P WHERE TopicFriendlyName = '';

declare @topicId uniqueidentifier
SELECT @topicId=TopicId FROM PFM_SVBS_Topic_P where TopicFriendlyName = '';

DELETE FROM PFM_SVBS_Subscription_P WHERE TopicId = @topicId;

declare @topicId uniqueidentifier
SELECT @topicId=TopicId FROM PFM_SVBS_Topic_P where TopicFriendlyName = '';

INSERT INTO PFM_SVBS_Subscription_P

  @topicId






  GETDATE()

  GETDATE()

-- Topics and Subscriptions
-- Topics and Subscriptions SELECT t.TopicId , TopicFriendlyName , TopicDescription , SubscriptionId , SubscriptionFriendlyName , SubscriptionDescription , ExternalSystemCode , SqlFilterExpression , ListenerTypeCode , t.ResourceTypeCode , s.LockDurationSeconds , s.MaxDeliveryCount , Convert( VarChar( 10 ), ListenerTimeOfDay, 114 ) as ListenerTimeOfDay FROM PFM_SVBS_Topic_P t LEFT OUTER JOIN PFM_SVBS_Subscription_P s ON t.TopicId = s.TopicId ORDER BY TopicFriendlyName , SubscriptionFriendlyName , ExternalSystemCode , ListenerTypeCode
-- Service Bus types SELECT lookupcode , displayname , comments , creatorid , createddate , LastUpdateId , LastUpdateDate FROM LU_PFM_SVBS_TYPE;
-- external systems SELECT ExternalSystemCode , tr.TopicId , t.TopicFriendlyName FROM PFM_SVBS_Topic_P_LookupExternalSystems_R tr JOIN PFM_SVBS_Topic_P t ON t.TopicId = tr.TopicId;
-- topics by type SELECT tt.TopicTypeCode , t.TopicId , t.TopicFriendlyName , tt.ExternalSystemCode , tr.DisplayName FROM PFM_SVBS_Topic_P_LU_PFM_SVBS_TYPE_R tt JOIN PFM_SVBS_Topic_P t ON tt.TopicId = t.TopicId JOIN LU_PFM_SVBS_TYPE tr ON tt.TopicTypeCode = tr.LookupCode
-- external systems SELECT lls.ExternalSystemCode , lls.ListenerTypeCode , lls.Configuration , lt.DisplayName FROM PFM_SVBS_LISTENERTYPE_LookupExternalSystems_R lls JOIN LU_PFM_SVBS_LISTENERTYPE lt ON lls.ListenerTypeCode = lt.LookupCode;
-- configuration SELECT ConfigurationAttributeCode , ExternalSystemCode , ListenerTypeCode , [Value] , Configuration , lta.DisplayName FROM PFM_SVBS_Configuration_Attribute_LookupExternalSystems_R la JOIN LU_PFM_SVBS_Configuration_Attribute lta ON la.ConfigurationAttributeCode = lta.LookupCode;
-- Subscriber Attributes SELECT ConfigurationAttributeCode , SubscriptionId , ListenerTypeCode , [Value] , lta.DisplayName FROM PFM_SVBS_Configuration_Attribute_Subscription_R la JOIN LU_PFM_SVBS_Configuration_Attribute lta ON la.ConfigurationAttributeCode = lta.LookupCode;
